#pragma once

#include <charconv>
#include <cstdint>
#include <optional>
#include <string_view>

namespace Ubiquitty::Linux {

/// Reads the flat, quoted hexadecimal accent field generated by Omarchy.
/// Extracts the top-level accent string emitted by Omarchy's theme generator.
[[nodiscard]] inline std::optional<std::uint32_t> parseOmarchyAccent(std::string_view text)
{
    const auto trim = [](std::string_view value) {
        const auto first = value.find_first_not_of(" \t\r");
        return first == std::string_view::npos ? std::string_view() : value.substr(first, value.find_last_not_of(" \t\r") - first + 1);
    };
    while (!text.empty()) {
        const auto end = text.find('\n');
        const auto line = trim(text.substr(0, end));
        text = end == std::string_view::npos ? std::string_view() : text.substr(end + 1);
        if (line.starts_with('['))
            break; // A nested table's accent is not the desktop accent.
        const auto equals = line.find('=');
        if (equals == std::string_view::npos || trim(line.substr(0, equals)) != "accent")
            continue;
        const auto value = trim(line.substr(equals + 1));
        if (value.size() < 9 || (value.front() != '\'' && value.front() != '"') || value[1] != '#' || value[8] != value.front())
            return std::nullopt;
        const auto trailing = trim(value.substr(9));
        if (!trailing.empty() && !trailing.starts_with('#'))
            return std::nullopt;
        std::uint32_t color = 0;
        const auto parsed = std::from_chars(value.data() + 2, value.data() + 8, color, 16);
        return parsed.ec == std::errc() && parsed.ptr == value.data() + 8 ? std::optional(color) : std::nullopt;
    }
    return std::nullopt;
}

} // namespace Ubiquitty::Linux
